import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Engineering Software with AI — Syllabus","description":"","frontmatter":{"source":"SYLLABUS.md"},"headers":[],"relativePath":"SYLLABUS.md","filePath":"SYLLABUS.md"}'),s={name:"SYLLABUS.md"};function n(i,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="engineering-software-with-ai--syllabus" tabindex="-1">Engineering Software with AI — Syllabus <a class="header-anchor" href="#engineering-software-with-ai--syllabus" aria-label="Permalink to &quot;Engineering Software with AI — Syllabus&quot;">​</a></h1><p><strong>Engineering practice for software built with AI coding agents, on a $0 budget.</strong> University of Idaho · CS [4xxx], joint-listed with CS [5xxx] · 3 credits · a 16-week semester · a 75-minute Seminar and a 75-minute Lab each week, plus about 6 hours outside class (about 7.5 for CS [5xxx]) · prerequisite: CS 3383 Software Engineering.</p><h2 id="course-information" tabindex="-1">Course information <a class="header-anchor" href="#course-information" aria-label="Permalink to &quot;Course information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Course title</strong></td><td>Engineering Software with AI</td></tr><tr><td><strong>Course number</strong></td><td>CS [4xxx], joint-listed with CS [5xxx]: a proposed new course for CS seniors and graduate students. The Registrar assigns both numbers when the University Curriculum Committee approves the course. 5000-level courses are restricted to students in the College of Graduate Studies, except that a senior with 90 or more credits and a 3.00 GPA may enroll with the required approvals (catalog Course Information; Regulation B-6). You earn credit for this course only at the level at which you first complete it; if you later take it at the other level, you won&#39;t receive credit (catalog Regulation B-11)</td></tr><tr><td><strong>Catalog description</strong> (proposed)</td><td>Engineering practice for software built with AI coding agents: how coding agents work; context engineering and specifications; verifying AI-written code with property-based and mutation testing; changing large existing codebases; code review and continuous integration at scale; securing agents against prompt injection and supply-chain attacks; building and evaluating LLM-based features; team workflows with parallel agents; and the evidence on productivity, quality and professional responsibility. Students work individually and in teams on a real open-source codebase. Additional projects/assignments required for graduate credit. (Joint-listed with CS [5xxx].) Prereq: CS 3383</td></tr><tr><td><strong>Institution</strong></td><td>University of Idaho</td></tr><tr><td><strong>Credits</strong></td><td>3. A credit means about 45 hours of work (catalog Regulation D-1), so plan on about <strong>135 hours</strong> in all: about 40 hours in class (30 meetings and the final defense) and about 90 hours outside, plus preparation for the defense (<a href="#4-how-the-course-works">section 4</a>). CS [5xxx] students do about 24–28 more hours of graduate work, for about 160 hours (<a href="#7-graduate-requirements-cs-5xxx">section 7</a>)</td></tr><tr><td><strong>Format and length</strong></td><td>In person. <strong>A 16-week semester</strong>: each week one 75-minute <strong>Seminar</strong> and one 75-minute <strong>Lab</strong>, plus about 6 hours of work outside class (CS [4xxx]) or about 7.5 hours (CS [5xxx]), so about <strong>8.5 hours a week</strong> (about 10 for CS [5xxx]). Weeks 1–15 are teaching weeks; week 16 is finals week</td></tr><tr><td><strong>Dates</strong></td><td><em>to be added</em></td></tr><tr><td><strong>Meeting times and rooms</strong></td><td>Seminar: <em>to be added</em> · Lab: <em>to be added</em></td></tr><tr><td><strong>Final exam period</strong></td><td>The <strong>final defense</strong>, in the course&#39;s scheduled 2-hour final exam slot in finals week (catalog Regulation H-1-b): <em>to be added</em></td></tr><tr><td><strong>Prerequisites</strong></td><td><strong>CS [4xxx]:</strong> CS 3383 Software Engineering with a grade of C or better. <strong>CS [5xxx]:</strong> graduate standing, and CS 3383 or an equivalent course, or instructor permission. Both levels assume you are comfortable with git, the command line, and Python or JavaScript</td></tr><tr><td><strong>Instructor</strong></td><td>Boyu Zhang, <em>title to be added</em></td></tr><tr><td><strong>Email and phone</strong></td><td><em>to be added</em> · Response time: <em>to be added</em></td></tr><tr><td><strong>Office</strong></td><td><em>to be added</em></td></tr><tr><td><strong>Office hours</strong></td><td><em>to be added</em></td></tr><tr><td><strong>Canvas</strong></td><td>Canvas, the course&#39;s learning management system: <em>link to be added</em>. Submissions, quizzes, grades, feedback and all graded personal writing go here</td></tr><tr><td><strong>Course website</strong></td><td><a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/" target="_blank" rel="noreferrer">boyu-zhang-uoi.github.io/engineering-software-with-ai</a> (all course materials)</td></tr><tr><td><strong>Required materials</strong></td><td>No textbook. Readings are free and linked from the <a href="./resources/reading-list.html">reading list</a>. A laptop that can run a browser-based Codespace, and free accounts (<a href="./setup/">setup</a>). Required cost: <strong>$0</strong> (<a href="#11-tools-and-cost">section 11</a>)</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Tool names are fine in this syllabus, but models, prices, limits and dates live only in <a href="./TOOLS.html">Tool Handout</a>, which carries a date and is re-checked before every term. That is deliberate: free tiers change monthly, and this syllabus should not.</p></div><p><strong>First step:</strong> work through <a href="./setup/">setup</a> in week 0 or the first days of week 1: accounts, the GitHub Student Developer Pack, API keys, a sandbox, and the agent safety contract.</p><hr><h2 id="1-course-description" tabindex="-1">1. Course description <a class="header-anchor" href="#1-course-description" aria-label="Permalink to &quot;1. Course description&quot;">​</a></h2><p>In 2025 &quot;vibe coding&quot; (describe what you want, accept what the AI writes, run it, repeat) went from a joke to a product category. By 2026 coding agents were opening hundreds of thousands of pull requests on GitHub, and the engineering questions had become the interesting ones. When an agent writes most of the code, who decides what it should do? How do you know it did that? How do you keep it from leaking your secrets or wrecking a codebase you inherited? And does any of this actually make teams faster?</p><p>This course answers those questions as engineering practice, at the level of a professional team. You will run, read and extend a small coding agent, and build an MCP server, so that the tools stop being magic. You will work inside a real, large open-source codebase all semester. You will measure whether your tests are adequate instead of trusting coverage, review AI-written pull requests against known defects, attack and defend an agent with prompt injection, build an LLM feature with evals you can defend, and run several agents in parallel without losing track of what they did. Throughout, you will read the evidence (randomized trials, field experiments, benchmark audits, maintainers&#39; policies) and learn to tell a measured effect from a marketing claim.</p><p>The course has one idea at its center, borrowed from UT Austin&#39;s CS 378: before any task, decide <strong>what you specify, what you delegate to an agent, and how you will verify the result</strong> (<a href="#specify--delegate--verify">section 4</a>). Everything else in the course is a way of doing one of those three things better.</p><p>Every required tool has a free tier, and the class has a lab machine that serves open-weight models. When a tool changes its limits, you switch to a fallback and keep working: that is part of the job.</p><h2 id="2-who-this-course-is-for" tabindex="-1">2. Who this course is for <a class="header-anchor" href="#2-who-this-course-is-for" aria-label="Permalink to &quot;2. Who this course is for&quot;">​</a></h2><ul><li><strong>Primary audience:</strong> CS seniors who have completed CS 3383, and graduate students in computer science or a related field. You already know software engineering process, testing, design and version control. This course doesn&#39;t re-teach them; it asks what changes when agents write much of the code. AI-specific terms (context window, tool call, MCP, mutation score, Cohen&#39;s κ) are defined when they first appear and collected in the <a href="./resources/glossary.html">glossary</a>.</li><li><strong>Graduate students (CS [5xxx]):</strong> you attend the same meetings, do the same labs and the same team project, and add a paper presentation, a critique and a small empirical study (<a href="#7-graduate-requirements-cs-5xxx">section 7</a>; <a href="./graduate/">graduate/</a>).</li><li><strong>Under 18, or studying from outside the US?</strong> Some free tiers have age and region rules (<a href="./TOOLS.html">Tool Handout</a> lists them). Tell the instructor in week 1, so we can plan your stack from the fallbacks and the lab machine.</li></ul><h3 id="how-it-differs-from-related-courses" tabindex="-1">How it differs from related courses <a class="header-anchor" href="#how-it-differs-from-related-courses" aria-label="Permalink to &quot;How it differs from related courses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>How this course relates to it</th></tr></thead><tbody><tr><td><strong>CS 3383 Software Engineering</strong></td><td>The prerequisite. This course assumes its requirements, design, testing and team practices, and applies them to agent-written code: specifications agents can follow, tests whose adequacy is measured, reviews at the volume agents produce</td></tr><tr><td><strong>CS 4800/4810 Senior Capstone</strong></td><td>Not a replacement. Capstone teams build for a customer. Here, teams contribute to an existing open-source codebase chosen by the instructor, and the subject is the engineering practice itself</td></tr><tr><td><strong>CS 5702 AI Governance, Ethics, and Professional Responsibility</strong></td><td>Not a replacement. This course&#39;s ethics content is the developer&#39;s practice: licensing, provenance, attribution, maintainers&#39; AI policies and privacy. Governance and the wider ethics of AI belong to CS 5702</td></tr><tr><td><strong>CS [2xxx] Building Apps with AI</strong> (the lower-division sibling course)</td><td>A course for students of any major who have taken one programming course: they build and ship web apps by directing AI tools (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/" target="_blank" rel="noreferrer">course website</a>). It is <strong>not</strong> a prerequisite. If you took it, you will recognize the Safe Loop; this course goes much further, into how agents work, large codebases, test adequacy, security and evals</td></tr></tbody></table><p><strong>What you need:</strong> a laptop with a modern browser (all required work runs in GitHub Codespaces or a dev container, so a modest laptop is fine), a GitHub account with the Student Developer Pack, and a phone for two-factor sign-in. The accounts are listed in <a href="./setup/">setup</a>.</p><h2 id="3-learning-outcomes" tabindex="-1">3. Learning outcomes <a class="header-anchor" href="#3-learning-outcomes" aria-label="Permalink to &quot;3. Learning outcomes&quot;">​</a></h2><p>By the end of the course, CS [4xxx] and CS [5xxx] students will be able to:</p><ol><li><strong>Explain</strong> how LLM coding agents work (model, context, tools, the loop, permissions, sandboxes), and run, read and extend a minimal one.</li><li><strong>Engineer context</strong> for agents: specifications, <code>AGENTS.md</code>, and tools exposed over MCP (the Model Context Protocol), and measure whether an agent follows them.</li><li><strong>Verify</strong> AI-written code with tests whose adequacy is measured (property-based testing, mutation testing) and enforced in continuous integration.</li><li><strong>Change large existing codebases</strong> safely: comprehend, characterize, refactor, and contribute changes that reviewers accept.</li><li><strong>Review</strong> code at scale: review AI-authored pull requests, and evaluate AI reviewers and static analysis against known defects.</li><li><strong>Secure</strong> AI-assisted development: threat-model agents, defend against prompt injection, and manage supply-chain, secret and permission risks.</li><li><strong>Build and evaluate</strong> LLM-based features with structured outputs and evals, including judge calibration, cost and latency.</li><li><strong>Evaluate evidence</strong> about AI in software engineering (benchmarks, productivity and quality studies) and act responsibly toward users, maintainers and licenses.</li></ol><p>CS [5xxx] students will also be able to:</p><ol start="9"><li><strong>Analyze and present</strong> research in AI for software engineering.</li><li><strong>Design and run</strong> a small empirical study and report it in a short paper.</li></ol><h3 id="how-each-outcome-is-assessed" tabindex="-1">How each outcome is assessed <a class="header-anchor" href="#how-each-outcome-is-assessed" aria-label="Permalink to &quot;How each outcome is assessed&quot;">​</a></h3><p>Every outcome maps to graded work (FSH 4700 F-4).</p><table tabindex="0"><thead><tr><th>Outcome</th><th>Where you show it</th><th>What the grader looks for</th></tr></thead><tbody><tr><td>1. Explain agents</td><td>Weeks 1–2 labs (your <code>mini-agent</code> tool and extension, the trace dissection, the onboarding report&#39;s comparison with <code>mini-agent</code>); the &quot;agent trace&quot; area of both <a href="./assessment/oral-exams.html">oral exams</a></td><td>A new tool and an extension to the agent loop, with tests written first; a trace in which every claim is tagged observed or inferred, and each inferred one is paired with the check that would settle it</td></tr><tr><td>2. Engineer context</td><td>Week 3 lab (MCP server, <code>AGENTS.md</code> A/B test); <code>AGENTS.md</code> in the team fork at <a href="./assessment/rubrics.html#m0-proposal">M0</a></td><td>A server that passes its protocol tests; an A/B test with a stated criterion for &quot;followed&quot;, honest about its sample size</td></tr><tr><td>3. Verify</td><td>Weeks 6–7 labs (property suite, mutation report); the Verification row of <a href="./assessment/rubrics.html#m2-major-contribution">M2</a>; &quot;reproducible checks&quot; at the <a href="./project/final-defense.html">final defense</a></td><td>Properties that find seeded bugs; mutation scores with surviving mutants explained; CI that fails when the tests fail</td></tr><tr><td>4. Change large codebases</td><td>Week 2 onboarding report; week 8 refactor; your PRs at <a href="./assessment/rubrics.html#m1-first-pr">M1</a> and M2; <a href="./assessment/rubrics.html#the-pr-round">the PR round</a></td><td>Characterization tests before the change; behavior shown unchanged; PRs a reviewer could accept</td></tr><tr><td>5. Review</td><td>Week 9 review lab; your reviews in the PR round and the team fork; the &quot;diff&quot; area of both oral exams</td><td>Precision and recall against the defect key; located, accurate review comments; a reasoned decision</td></tr><tr><td>6. Secure</td><td>Week 4 injection lab and <code>THREAT_MODEL.md</code>; week 10 scan-and-fix and security review; the Security row of M2</td><td>Defenses that hold against a stubbed model that obeys the injection; findings fixed with regression tests</td></tr><tr><td>7. Build and evaluate LLM features</td><td>Weeks 11–12 labs (extractor, error analysis, eval report); the Evals row of M2 when the contribution uses an LLM</td><td>Validated structured output; an eval set with field-level metrics; a judge reported with percent agreement <strong>and</strong> Cohen&#39;s κ; an offline CI gate</td></tr><tr><td>8. Evaluate evidence, act responsibly</td><td><a href="./assessment/rubrics.html#reading-responses-and-seminar-participation">Reading responses</a>; the week 14 debate; the &quot;honest limitations&quot; rows of the final report and defense; <a href="./project/contribution-rules.html">contribution rules</a> for any upstream PR</td><td>Claims stated with their evidence and its limits; disclosure that matches the record</td></tr><tr><td>9. Analyze and present research (CS [5xxx])</td><td><a href="./graduate/paper-presentations.html">Paper presentation and discussant</a>; the critique</td><td>The CU Boulder-style rubric: content, value added, materials, leading discussion</td></tr><tr><td>10. Design and run a study (CS [5xxx])</td><td><a href="./graduate/empirical-study.html">Empirical study</a>: protocol, interim results, talk, paper</td><td>A preregistered protocol followed (or deviations reported), results with uncertainty, threats to validity, a reproducible artifact</td></tr></tbody></table><p><strong>Example: how outcome 3 is assessed.</strong> In week 7 you run StrykerJS (a mutation-testing tool: it makes small changes to the code, called mutants, and checks whether your tests notice) on one <code>roomly</code> module, raise its mutation score with tests you can justify, and explain the mutants that survive, including any that are equivalent to the original code. The grader checks the command, the before and after scores, and your reasoning about each survivor (<a href="./assessment/rubrics.html#labs-and-assignments">labs rubric</a>). At M2 the same evidence is required for your team&#39;s own contribution, and at the final defense you rerun one check live.</p><h2 id="4-how-the-course-works" tabindex="-1">4. How the course works <a class="header-anchor" href="#4-how-the-course-works" aria-label="Permalink to &quot;4. How the course works&quot;">​</a></h2><h3 id="the-seminar-and-the-lab" tabindex="-1">The Seminar and the Lab <a class="header-anchor" href="#the-seminar-and-the-lab" aria-label="Permalink to &quot;The Seminar and the Lab&quot;">​</a></h3><p>Weeks 1–15 each have two 75-minute meetings a few days apart: the <strong>Seminar</strong> (concepts, the reading, demos and debate) and the <strong>Lab</strong> (hands-on work with staff checkoffs). Week 16 is finals week: there are no regular meetings, and the <a href="./project/final-defense.html">final defense</a> runs in the course&#39;s scheduled 2-hour final exam slot (Regulation H-1-b). Each week&#39;s <code>README.md</code> opens with a <strong>This week at a glance</strong> table: what to do before the Seminar, what each meeting covers, what&#39;s due, the AI rules, the reading and the time it takes.</p><table tabindex="0"><thead><tr><th>Block</th><th>Time</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Seminar</strong></td><td>75 min</td><td>Due-date quiz when something is due (7 min, 🔴 AI off) · concept talk (25 minutes at most) · reading discussion or debate (20 min) · live demo (10 min) · Lab preview (5 min). In a week with a graduate paper presentation: concept talk 18 · presentation 20 · discussion led by the presenter 12</td></tr><tr><td><strong>Lab</strong></td><td>75 min</td><td>Setup check (5 min) · guided lab (about 50 min) · <strong>checkoff</strong>: staff check the week&#39;s in-lab deliverable (15 min) · next steps (5 min)</td></tr><tr><td><strong>Outside class</strong></td><td>about 6 h (CS [5xxx]: about 7.5 h)</td><td>The reading and your reading response (about 45 min) · the week&#39;s assignment, which continues the Lab (about 3.5 h) · team project work (about 1.75 h) · CS [5xxx]: graduate work (about 1.5 h)</td></tr></tbody></table><p>Some weeks move minutes between blocks, but every meeting stays at 75 minutes. The PR round adds about 4 hours in week 9 and about 2 in week 10, so week 9 takes about 9–10 hours outside class (CS [5xxx]: about 1.5 more).</p><ul><li><strong>Due dates.</strong> The take-home <strong>assignment</strong> continues the Lab and is <strong>due before next week&#39;s Seminar (default 11:59 pm the night before)</strong>. Canvas shows the exact time. Each <code>lab.md</code> ends with the assignment, its rubric summary, its due line and a &quot;Minimum to keep up&quot; box.</li><li><strong>Due-date quizzes.</strong> On the day an assignment is due, the Seminar opens with a <strong>7-minute AI-free quiz about that assignment</strong>, a practice from UT Austin&#39;s CS 378. If you did the work and understood what your agent did, the quiz is easy; if an agent did it for you, it isn&#39;t. Weeks 2–14 only; there is no quiz in week 15, because Regulation H-1-a says: &quot;No quizzes or exams may be given in lecture-recitation periods during the week before finals week.&quot; Rules, examples and drops: <a href="./assessment/quizzes.html">Due-Date Quizzes</a>.</li><li><strong>Reading responses.</strong> Each week has one short reading, linked from the week&#39;s README and the <a href="./resources/reading-list.html">reading list</a>. Before the Seminar, write a 150–250-word <strong>reading response</strong> on Canvas (🔴 AI off): the claim, the evidence for it and how strong that evidence is, what it means for your own practice, and one question for the discussion. (Week 1&#39;s response is due before the week 1 Lab.)</li><li><strong>Oral exams.</strong> Two 15-minute, individual, 🔴 AI-off <strong>oral exams</strong>, in weeks 8 and 14, held in the Lab and in office-hour slots that week (<a href="./assessment/oral-exams.html">Oral Exams</a>). Slots outside class time are scheduled at least two weeks ahead and announced in the first week; I cancel equivalent Lab time to make room for them, and anyone with a conflict gets another time (catalog Regulation O-9-c).</li><li><strong>Core and if-time.</strong> Every lab part is marked <strong>Core</strong> or <strong>If time</strong>. Only the core is required for the checkoff.</li></ul><h3 id="specify--delegate--verify" tabindex="-1">Specify · Delegate · Verify <a class="header-anchor" href="#specify--delegate--verify" aria-label="Permalink to &quot;Specify · Delegate · Verify&quot;">​</a></h3><p>UT Austin&#39;s CS 378 treats using coding agents as a skill you practice like technical writing, and splits every problem into &quot;what you specify, what you delegate, and what you verify&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>). This course adopts that triad as its core habit. Before any non-trivial task, write three lines in your <code>AI_LOG.md</code> (<a href="./templates/AI_LOG.html">template</a>):</p><table tabindex="0"><thead><tr><th></th><th>You decide</th><th>Example</th></tr></thead><tbody><tr><td><strong>Specify</strong></td><td>What &quot;done&quot; means, in checkable terms, and what must not change</td><td>&quot;Recurring bookings expand into at most 52 instances; existing single bookings keep their IDs; no new dependencies&quot;</td></tr><tr><td><strong>Delegate</strong></td><td>Which agent does which part, with which permissions</td><td>&quot;OpenCode in a Codespace, approvals on, may edit <code>src/recurrence/</code> and its tests only&quot;</td></tr><tr><td><strong>Verify</strong></td><td>How you will know it worked, before you see the output</td><td>&quot;Property: no two expanded instances overlap; mutation score on <code>recurrence.js</code> stays at least what it was; I read the full diff&quot;</td></tr></tbody></table><p>After the task, record what happened: what the agent did, what your checks caught, and what you changed. That record is what you&#39;re graded on, much more than the size of the diff.</p><h3 id="the-safe-loop" tabindex="-1">The Safe Loop <a class="header-anchor" href="#the-safe-loop" aria-label="Permalink to &quot;The Safe Loop&quot;">​</a></h3><p>The inner loop is the one the lower-division course teaches, the <strong>Safe Loop</strong>: <strong>Describe → Plan → Step → Test → Read → Commit</strong>. Describe the goal, constraints and &quot;done when&quot;; get a plan and edit it before any code is written; take one small step; run your checks; read the diff and keep only what you can explain; commit with a clear message. If two attempts at the same fix fail, stop and rewrite the prompt with what you learned. Seniors get the one-page version: <a href="./resources/safe-loop.html">Specify · Delegate · Verify, and the Safe Loop</a>. Specify · Delegate · Verify is the plan around a task; the Safe Loop is how you execute it.</p><p>Commits made with AI help end with an <code>Assisted-by: [tool and model]</code> trailer, the convention LLVM&#39;s AI policy uses (<a href="https://github.com/llvm/llvm-project/blob/main/llvm/docs/AIToolPolicy.md" target="_blank" rel="noreferrer">LLVM</a>). Pull-request descriptions are written by you, not generated (LLVM asks the same), and every PR template has an AI disclosure section (<a href="./templates/PULL_REQUEST_TEMPLATE.html">template</a>).</p><h3 id="observed-and-inferred" tabindex="-1">Observed and inferred <a class="header-anchor" href="#observed-and-inferred" aria-label="Permalink to &quot;Observed and inferred&quot;">​</a></h3><p>Every claim you make about a codebase, an agent or a tool is tagged <strong>observed</strong> (you ran it or read it yourself) or <strong>inferred</strong> (you or the AI concluded it). &quot;The retry loop gives up after three attempts (observed: <code>client.js</code> line 88, and the test <code>retries three times</code>)&quot; is a different kind of claim from &quot;the cache is probably invalidated on write (inferred from the agent&#39;s summary)&quot;. Agents produce confident summaries of code they haven&#39;t fully read; tagging forces you to check the claims that matter. The practice is adapted from Stanford CS146S, whose assignments ask students to &quot;scope your claims to what [the evidence] supports&quot; (<a href="https://themodernsoftware.dev/" target="_blank" rel="noreferrer">CS146S</a>).</p><h3 id="the-tool-ladder" tabindex="-1">The tool ladder <a class="header-anchor" href="#the-tool-ladder" aria-label="Permalink to &quot;The tool ladder&quot;">​</a></h3><p>The course climbs from tools you can read line by line to tools that work while you&#39;re not watching. Each rung comes after the safeguards it needs: prompt injection and sandboxing are taught in week 4, before teams give agents broad access to the class codebase.</p><table tabindex="0"><thead><tr><th>Weeks</th><th>Rung</th><th>Examples (current picks and fallbacks: <a href="./TOOLS.html">Tool Handout</a>)</th><th>What you supervise</th></tr></thead><tbody><tr><td>1–4</td><td><strong>Your own agent</strong> and a chat assistant</td><td>The course&#39;s <code>mini-agent</code> kit, against a free API or the lab machine&#39;s local models</td><td>Every request and every tool call, in a trace you can read</td></tr><tr><td>2–8</td><td><strong>An IDE agent</strong> in a sandbox</td><td>Copilot in VS Code in a Codespace (used lightly), Zed, Cline</td><td>Multi-file edits you approve one by one</td></tr><tr><td>2–12</td><td><strong>CLI agents</strong> on the class codebase</td><td>Gemini CLI, OpenCode, Copilot CLI, against free tiers or the lab machine</td><td>Longer tasks, with command approvals</td></tr><tr><td>9–12</td><td><strong>AI reviewers and analyzers</strong> in CI</td><td>CodeRabbit or PR-Agent on public forks, CodeQL, Semgrep</td><td>Comments and findings you evaluate against known defects</td></tr><tr><td>13</td><td><strong>Parallel and background agents</strong></td><td>Several CLI agents in git worktrees; Jules or a cloud agent on your own fork</td><td>Many tasks at once: you are the integrator and the reviewer</td></tr></tbody></table><h2 id="5-weekly-schedule" tabindex="-1">5. Weekly schedule <a class="header-anchor" href="#5-weekly-schedule" aria-label="Permalink to &quot;5. Weekly schedule&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Title</th><th>Seminar</th><th>Lab and assignment</th><th>Team project / graduate</th></tr></thead><tbody><tr><td>0</td><td><a href="./setup/">Setup</a></td><td>—</td><td>Accounts, the Student Developer Pack, API keys, a sandbox, local models</td><td>—</td></tr><tr><td>1</td><td><a href="./weeks/01-agentic-engineering/">From Vibe Coding to Agentic Engineering</a></td><td>Specify · Delegate · Verify; LLMs for engineers; maintainers vs graders</td><td>Run, read and extend a coding agent (<code>mini-agent</code>); trace dissection</td><td>Agent safety contract; team survey</td></tr><tr><td>2</td><td><a href="./weeks/02-inside-agents/">Inside Real Agents</a></td><td>Harness architecture; reading a large codebase</td><td>Onboard to the class codebase; onboarding report</td><td>Teams of 3–4; <code>TEAM_CHARTER.md</code></td></tr><tr><td>3</td><td><a href="./weeks/03-context-engineering/">Context Engineering</a></td><td><code>AGENTS.md</code>, rules, skills, MCP; context rot</td><td>MCP from scratch; <code>AGENTS.md</code> A/B test</td><td>Grad: paper presentations begin</td></tr><tr><td>4</td><td><a href="./weeks/04-securing-agents/">Securing Agents</a></td><td>Prompt injection; the lethal trifecta; sandboxes and secrets</td><td>Injection lab: attack, then defend; <code>THREAT_MODEL.md</code></td><td>—</td></tr><tr><td>5</td><td><a href="./weeks/05-spec-driven-development/">Spec-Driven Development</a></td><td>Requirements → design → tasks; EARS; specs that change</td><td><code>roomly</code>: spec and build recurring bookings; beat 2</td><td><strong>M0</strong> proposal</td></tr><tr><td>6</td><td><a href="./weeks/06-tests-as-oracles/">Tests as Oracles</a></td><td>Test oracles; TDD with agents; property-based testing</td><td>Property-based testing of <code>roomly</code>; bug reports</td><td>Grad: study protocol</td></tr><tr><td>7</td><td><a href="./weeks/07-test-adequacy/">Measuring Test Adequacy</a></td><td>Coverage vs mutation score; equivalent mutants</td><td>Mutation testing of <code>roomly</code>; raise a module&#39;s score</td><td>—</td></tr><tr><td>8</td><td><a href="./weeks/08-legacy-code/">Legacy Code</a></td><td>Characterization tests, seams, refactoring with agents</td><td>Characterize and refactor <code>roomly</code>&#39;s god module; <strong>oral exam 1</strong></td><td><strong>M1</strong> first PR</td></tr><tr><td>9</td><td><a href="./weeks/09-review-at-scale/">Review at Scale</a></td><td>Reviewing AI-authored PRs; AI reviewers; CI gates</td><td>Review lab vs an AI reviewer; CI on the team fork</td><td><strong>PR round</strong> opens</td></tr><tr><td>10</td><td><a href="./weeks/10-supply-chain/">Supply Chain and Secure Code</a></td><td>Insecure-but-working code; slopsquatting; secrets; SBOMs</td><td>Scan and fix; security review of the team&#39;s work</td><td>PR round closes</td></tr><tr><td>11</td><td><a href="./weeks/11-llm-features/">Building LLM Features</a></td><td>Structured outputs, validation, cost and latency</td><td><code>eval-harness</code>: a validated extractor; one measured improvement and an error analysis</td><td>Grad: interim results</td></tr><tr><td>12</td><td><a href="./weeks/12-evals/">Evals</a></td><td>Eval design; LLM-as-judge calibration; benchmark limits</td><td>Eval set, calibrated judge, offline CI gate</td><td><strong>M2</strong> major contribution; grad: critique</td></tr><tr><td>13</td><td><a href="./weeks/13-parallel-agents/">Parallel and Background Agents</a></td><td>Worktrees, cloud agents, orchestration, governance</td><td>Three agents on three issues; team retrospective</td><td>—</td></tr><tr><td>14</td><td><a href="./weeks/14-evidence-and-responsibility/">Evidence and Responsibility</a></td><td>Structured debate: productivity, quality and skills evidence; maintainers&#39; policies; licensing</td><td><strong>Oral exam 2</strong>; final-report sprint and draft</td><td>Grad: paper draft</td></tr><tr><td>15</td><td><a href="./weeks/15-ship-and-reflect/">Ship and Reflect</a></td><td>Where the field is going; retrospective (no quiz)</td><td>Integration sprint; defense dry run</td><td>Grad: study talks</td></tr><tr><td>16</td><td><a href="./weeks/16-final-defense/">Final Defense</a> (finals week)</td><td>—</td><td>The final defense in the final exam slot</td><td>Final report; grad final paper</td></tr></tbody></table><h3 id="week-by-week-detail" tabindex="-1">Week-by-week detail <a class="header-anchor" href="#week-by-week-detail" aria-label="Permalink to &quot;Week-by-week detail&quot;">​</a></h3><p>Unless a week says otherwise, the assignment is due before next week&#39;s Seminar (default 11:59 pm the night before), and the next Seminar opens with a 7-minute quiz on it. Each week also has a reading and a reading response.</p><p><strong>Week 0 — Setup.</strong> Before or during the first days of week 1 (<a href="./setup/">setup</a>): create your accounts, apply for the GitHub Student Developer Pack (verification can take days), get a free LLM API key, open a test Codespace, check that you can reach the lab machine&#39;s local models, and read the agent safety contract. Turn off &quot;train on my data&quot; settings where a tool offers them.</p><p><strong>Week 1 — From Vibe Coding to Agentic Engineering.</strong> <em>Seminar:</em> the course&#39;s framing, Specify · Delegate · Verify; LLMs for engineers: tokens, context windows, sampling, tool calling and cost; and a teaser from the evidence: maintainers merged far fewer test-passing agent PRs than an automated grader accepted. The agent safety contract and the data rule. <em>Lab:</em> <strong>run and read a coding agent</strong>, the <a href="https://github.com/Boyu-Zhang-UOI/eswa-mini-agent" target="_blank" rel="noreferrer"><code>mini-agent</code> kit</a>: its loop, its tools, its approval gate and its trace, on a task where you approve every write and command. <em>Assignment:</em> extend the agent with one new tool and one extension (a smarter approval policy, compaction or a bash-only mode), each with tests that run offline against a scripted model, and write a <strong>trace dissection</strong> of a session with a real CLI agent: its system prompt, its tool schemas and its tool calls, with every claim tagged observed or inferred. Also this week: sign the agent safety contract on Canvas and fill in the team-formation survey. CS [5xxx]: rank three papers for your presentation. No quiz.</p><p><strong>Week 2 — Inside Real Agents.</strong> <em>Seminar:</em> harness architecture: system prompts, tool schemas, context management and compaction, subagents, permissions and sandboxes; how an agent (and you) should read a large codebase. <em>Lab:</em> <strong>onboard to the class codebase</strong> (<a href="./project/class-codebase.html">The Class Codebase</a>): build it in a Codespace, run its tests, map its architecture with an agent, and check the map&#39;s claims against the code. <em>Assignment:</em> an individual <strong>onboarding report</strong>. <em>Team project:</em> teams of 3–4 are announced; your team writes <code>TEAM_CHARTER.md</code> (<a href="./templates/TEAM_CHARTER.html">template</a>), due with the assignment.</p><p><strong>Week 3 — Context Engineering.</strong> <em>Seminar:</em> <code>AGENTS.md</code>, rules, skills and MCP; context rot (model performance falls as the input grows); the evidence on committed configuration files. <em>Lab:</em> <strong>MCP from scratch</strong> with the <a href="https://github.com/Boyu-Zhang-UOI/eswa-mcp-from-scratch" target="_blank" rel="noreferrer"><code>mcp-from-scratch</code> kit</a>: JSON-RPC over stdio, the handshake, tool listing and tool calls, tested through a child process; then add a tool of your own and get an agent to call it. <em>Assignment:</em> write an <code>AGENTS.md</code> for the class codebase (<a href="./templates/AGENTS.html">template</a>) and run an <strong>A/B test</strong> of whether an agent follows it on two tasks, with a criterion for &quot;followed&quot; fixed before you look at the results. CS [5xxx]: paper presentations begin.</p><p><strong>Week 4 — Securing Agents.</strong> <em>Seminar:</em> prompt injection, direct and indirect; the &quot;lethal trifecta&quot; (private data, untrusted content and a way to send data out, in one agent); MCP tool poisoning; permissions, sandboxes and secrets for agents. Taught now, before teams give agents broad access. <em>Lab:</em> the <strong>injection lab</strong> (<a href="https://github.com/Boyu-Zhang-UOI/eswa-injection-lab" target="_blank" rel="noreferrer"><code>injection-lab</code> kit</a>): a poisoned README and issue try to make your <code>mini-agent</code> leak a worthless canary secret to an &quot;attacker&quot; server on localhost. Attack first, then defend: a tool allowlist, approvals, an egress block and quarantined reading. <em>Assignment:</em> extend one defense, with tests showing that it stops a stubbed model that obeys the injection, plus a threat model of your team&#39;s own agent setup in <code>THREAT_MODEL.md</code> (<a href="./templates/THREAT_MODEL.html">template</a>).</p><p><strong>Week 5 — Spec-Driven Development.</strong> <em>Seminar:</em> requirements, then design, then tasks; acceptance criteria in EARS form (the Easy Approach to Requirements Syntax: &quot;WHEN [trigger] THE [system] SHALL [response]&quot;); plan mode; splitting work into agent-sized tasks; specs that change under you (&quot;beats&quot;, from UT Austin). <em>Lab:</em> the <a href="https://github.com/Boyu-Zhang-UOI/eswa-roomly" target="_blank" rel="noreferrer"><code>roomly</code> kit</a>, a deliberately messy room-booking service: specify recurring bookings in <code>SPEC.md</code>, <code>DESIGN.md</code> and <code>TASKS.md</code>, then build its first task with an agent in small verified steps. <em>Assignment:</em> finish the feature; <strong>beat 2</strong> changes the spec halfway through, and you report how your spec, design and tasks absorbed the change. <em>Team project:</em> <strong>M0 proposal</strong> due before the week 6 Seminar (<a href="./project/milestones.html">milestones</a>).</p><p><strong>Week 6 — Tests as Oracles.</strong> <em>Seminar:</em> test oracles; tests that agree with bugs (LLM-written oracles tend to capture what the code does, not what it should do); test-driven development with agents; property-based testing; the evidence on LLM-written tests. <em>Lab:</em> <strong>property-based testing</strong> of <code>roomly</code>&#39;s time and overlap logic with fast-check: find the seeded bugs, and judge the properties an agent proposes. <em>Assignment:</em> a property suite; a bug report for each real bug it finds, with a minimal failing case; and a fix for each, regression test first. CS [5xxx]: <strong>study protocol</strong> due before the week 7 Seminar.</p><p><strong>Week 7 — Measuring Test Adequacy.</strong> <em>Seminar:</em> coverage versus mutation score; mutation-guided test generation at Meta; equivalent mutants; the ISSTA 2026 caveat (for LLM-written suites, coverage and mutation score track bug-finding poorly when the code may already be wrong). <em>Lab:</em> <strong>mutation testing</strong> of <code>roomly</code> with StrykerJS: the shipped tests, an agent-written batch and your week 6 properties on one module; triage the survivors. <em>Assignment:</em> raise one module&#39;s mutation score with tests you can justify, compare an agent-written batch with yours, and report the scores, the command and every surviving mutant.</p><p><strong>Week 8 — Legacy Code.</strong> <em>Seminar:</em> characterization tests, seams, refactoring and migrations with agents; the Cursor adoption study (output rose, then fell back, while warnings and complexity stayed up). <em>Lab:</em> <strong>characterize and refactor</strong> <code>roomly</code>&#39;s god module with an agent, and prove its behavior unchanged with characterization tests and the mutation score. <strong>Oral exam 1</strong> runs in the Lab and in office-hour slots this week. <em>Assignment:</em> finish the refactor with before-and-after evidence. <em>Team project:</em> <strong>M1</strong> (each member&#39;s first PR in the team fork, reviewed by a teammate, CI green), peer evaluation 1 and your team&#39;s <a href="./project/pr-round.html#before-the-round">PR-round preparation</a>, due before the week 9 Seminar.</p><p><strong>Week 9 — Review at Scale.</strong> <em>Seminar:</em> reviewing AI-authored PRs (size, review burden, follow-up fixes); AI reviewers in production; static analysis; CI gates. <em>Lab:</em> the <strong>review lab</strong>: seeded PRs against <code>roomly</code>; your review versus an AI reviewer, both scored against the defect key for precision and recall. Then set up CI on your team fork (tests, lint, and CodeQL or Semgrep). <em>Assignment:</em> the review report and the CI setup. <em>Team project:</em> <strong>the PR round</strong> opens: every student opens one PR on another team&#39;s fork, due before the week 10 Seminar (<a href="./project/pr-round.html">The PR Round</a>).</p><p><strong>Week 10 — Supply Chain and Secure Code.</strong> <em>Seminar:</em> insecure-but-working code (in BaxBench, about half of the functionally correct backends were exploitable); package hallucination and slopsquatting; dependency confusion; secrets in agent workflows; provenance and SBOMs (software bills of materials); the 2025–26 incidents. <em>Lab:</em> <strong>scan and fix</strong>: CodeQL or Semgrep, <code>npm audit</code>, package-name verification and a secret scan that covers git history, on <code>roomly</code> and your team fork; fix one finding with a regression test. <em>Assignment:</em> a security review of your team&#39;s contributions. <em>Team project:</em> the PR round closes before the week 11 Seminar: review the PRs your team received and record a decision on each.</p><p><strong>Week 11 — Building LLM Features.</strong> <em>Seminar:</em> structured outputs, tool calling, validation and retries, cost and latency budgets, retrieval basics. <em>Lab:</em> the <a href="https://github.com/Boyu-Zhang-UOI/eswa-eval-harness" target="_blank" rel="noreferrer"><code>eval-harness</code> kit</a>, a natural-language-to-booking extractor with schema validation and retries: replay its 30 recorded cases, read the schema and the retry loop, then run it live and record your own baseline with its cost and latency log. <em>Assignment:</em> an <strong>error analysis</strong> of the 30 cases, and one improvement measured against your baseline. CS [5xxx]: <strong>interim results</strong> due before the week 12 Seminar.</p><p><strong>Week 12 — Evals.</strong> <em>Seminar:</em> eval design and metrics; LLM-as-judge pitfalls and calibration (report Cohen&#39;s κ, the agreement beyond chance, and not only percent agreement); regression evals in CI; benchmarks and their limits (contamination, and maintainers versus graders). <em>Lab:</em> label outputs blind, calibrate a judge against your own labels, and add a CI gate that runs on recorded responses. <em>Assignment:</em> an eval report on an extended eval set (<a href="./templates/EVAL_PLAN.html">template</a>). <em>Team project:</em> <strong>M2</strong> (a major contribution with spec, tests, mutation score and security review, plus evals if it uses an LLM) and peer evaluation 2, due before the week 13 Seminar. Optional upstream PRs may start this week (<a href="./project/contribution-rules.html">contribution rules</a>). CS [5xxx]: the <strong>critique</strong> is due before the week 13 Seminar.</p><p><strong>Week 13 — Parallel and Background Agents.</strong> <em>Seminar:</em> git worktrees, issue-to-PR cloud agents, orchestration, merge conflicts, human-in-the-loop governance and cost; UT Austin&#39;s rule of thumb: &quot;Parallelize a task once you can name its merge point&quot;. <em>Lab:</em> run <strong>three agents in parallel</strong> on three <code>roomly</code> issues (in worktrees; one may be a background agent), integrate their work, and measure your own review time. <em>Assignment:</em> your team&#39;s <strong>process retrospective with data</strong> (review time, follow-up fixes on agent PRs, CI failures).</p><p><strong>Week 14 — Evidence and Responsibility.</strong> <em>Seminar:</em> a <strong>structured debate</strong> on the evidence: productivity (the METR randomized trial, field experiments, DORA), quality and skills; maintainers&#39; AI policies (QEMU, Ghostty, LLVM); licensing and attribution; privacy. Every claim in the debate needs a source, and opinion is labeled as opinion. <em>Lab:</em> <strong>oral exam 2</strong> in the Lab and in office-hour slots this week (all slots inside week 14); staff screen optional upstream PRs; team time on the report. <em>Assignment:</em> your team&#39;s <strong>final report draft</strong>, due before the week 15 Seminar. CS [5xxx]: <strong>paper draft</strong> due before the week 15 Seminar.</p><p><strong>Week 15 — Ship and Reflect.</strong> <em>Seminar:</em> where the field is going, and a course retrospective; CS [5xxx] <strong>study talks</strong> (10 minutes each; a presentation is not an exam). No quiz and no oral exam (Regulation H-1-a). <em>Lab:</em> a final integration sprint and a <strong>defense dry run</strong>: practice only, ungraded, with no exam-like activity.</p><p><strong>Week 16 — Final Defense (finals week).</strong> No regular meetings. The <strong>final defense</strong> runs in the course&#39;s scheduled 2-hour final exam slot (Regulation H-1-b): each team demonstrates its contribution and runs a reproducible check live, then each member answers individual questions with the AI off (<a href="./project/final-defense.html">The Final Defense</a>). The <strong>repository snapshot</strong> is your team fork&#39;s <code>main</code> at the start of the slot, which staff tag <code>final</code>. The <strong>final report</strong>, peer evaluation 3 and the CS [5xxx] <strong>final paper</strong> are due on Canvas by 11:59 pm on the last day of finals week.</p><h2 id="6-the-team-project" tabindex="-1">6. The team project <a class="header-anchor" href="#6-the-team-project" aria-label="Permalink to &quot;6. The team project&quot;">​</a></h2><p>The team project runs from week 2 to finals week, in <strong>the class codebase</strong>: a class fork of a real, active open-source project, chosen by the instructor before the term (<a href="./project/class-codebase.html">The Class Codebase</a>). The default candidates are open-source coding agents, so that the codebase also teaches the course&#39;s subject. Teams have 3–4 members; CS [5xxx] students may be on mixed teams.</p><p>It has three tiers. The first is graded; the second is graded individually; the third is optional. Following Michigan&#39;s EECS 481 experience, the course grades your process, never whether a maintainer merges your work (<a href="./project/">The Team Project</a>).</p><table tabindex="0"><thead><tr><th>Tier</th><th>What</th><th>Graded as</th></tr></thead><tbody><tr><td><strong>1. Core work in your team fork</strong></td><td>Each team works in its own fork of the class fork. PRs go to the team fork, reviewed by teammates; grading uses a snapshot of the fork (including open branches and PRs) at each deadline</td><td>Milestones M0, M1, M2 and Final</td></tr><tr><td><strong>2. The PR round</strong> (weeks 9–10)</td><td>Every student opens one PR on another team&#39;s fork; the receiving team reviews it and decides</td><td><a href="./assessment/rubrics.html#the-pr-round">The PR round rubric</a>, in Labs and assignments</td></tr><tr><td><strong>3. Optional upstream PRs</strong> (weeks 12–15)</td><td>A change already reviewed in your team fork, offered to the parent project or a short pre-vetted list, only where the project&#39;s written policy allows disclosed AI assistance. Staff screen your first one</td><td>A small bonus if merged; never a penalty (<a href="./project/contribution-rules.html">contribution rules</a>)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Milestone</th><th>Due</th><th>Points</th></tr></thead><tbody><tr><td><strong>M0 proposal</strong></td><td>End of week 5 (before the week 6 Seminar)</td><td>15</td></tr><tr><td><strong>M1 first PR</strong></td><td>End of week 8 (before the week 9 Seminar)</td><td>30</td></tr><tr><td><strong>M2 major contribution</strong></td><td>End of week 12 (before the week 13 Seminar)</td><td>40</td></tr><tr><td><strong>Final</strong> (report, repository snapshot, final defense)</td><td>Finals week</td><td>65</td></tr></tbody></table><p>Deliverables are defined once, in <a href="./project/milestones.html">Team Project Milestones</a>. Each milestone has team rows and individual rows, and <strong>peer evaluations on Canvas</strong> at M1, M2 and Final, with the contribution evidence in the repository, can adjust an individual&#39;s share of the team rows (<a href="./assessment/#team-grades-and-peer-evaluation">how</a>).</p><p><strong>Rules for the team project:</strong> work only on public open-source code and the course kits; no real personal data or secrets anywhere; follow the agent safety contract; never send course work to the parent project except through Tier 3.</p><h2 id="7-graduate-requirements-cs-5xxx" tabindex="-1">7. Graduate requirements (CS [5xxx]) <a class="header-anchor" href="#7-graduate-requirements-cs-5xxx" aria-label="Permalink to &quot;7. Graduate requirements (CS [5xxx])&quot;">​</a></h2><p>The catalog says it in UIdaho&#39;s usual words: &quot;Additional projects/assignments required for graduate credit.&quot; Concretely, CS [5xxx] students do everything above plus about 1.5 hours a week of graduate work (<a href="./graduate/">Graduate Work (CS [5xxx])</a>):</p><ul><li><strong>A paper presentation and a discussant role</strong> (one of each): a 20-minute presentation of a paper from the reading list&#39;s graduate seminar set, in a Seminar in weeks 3–14, scored on CU Boulder&#39;s rubric (content 30, value added 30, materials 20, leading discussion 20); as discussant for a classmate&#39;s paper, you prepare three questions. Every other student posts one question before each presentation (<a href="./graduate/paper-presentations.html">paper presentations</a>).</li><li><strong>A critique</strong> of one paper (1,000 words), or a &quot;tool experience report&quot; in which you run a research tool on your own use case, on Canvas before the week 13 Seminar (<a href="./graduate/#the-critique">critique</a>).</li><li><strong>An empirical study</strong>, alone or in a pair: a small replication or extension, at $0, from the course&#39;s list of replicable studies or an approved proposal. Protocol in week 6, interim results in week 11, a draft in week 14, a 10-minute talk in week 15, and a 4–6 page paper in ACM format in finals week. <strong>No human-subjects work</strong> (no studying classmates or maintainers) without IRB approval (<a href="./graduate/empirical-study.html">empirical study</a>).</li></ul><h2 id="8-assessment" tabindex="-1">8. Assessment <a class="header-anchor" href="#8-assessment" aria-label="Permalink to &quot;8. Assessment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>CS [4xxx]</th><th>CS [5xxx]</th><th>How it is graded</th></tr></thead><tbody><tr><td>Labs and assignments</td><td>35%</td><td>30%</td><td>Weeks 1–13, each 20 points (checkoff 5, assignment 15), lowest week dropped; plus the PR round, 20 points (<a href="./assessment/rubrics.html#labs-and-assignments">rubric</a>)</td></tr><tr><td>Due-date quizzes</td><td>10%</td><td>5%</td><td>7 minutes, AI-free, weeks 2–14; lowest two dropped (<a href="./assessment/quizzes.html">quizzes</a>)</td></tr><tr><td>Team project</td><td>30%</td><td>25%</td><td>M0 15 · M1 30 · M2 40 · Final 65 points, the same for both levels; for CS [4xxx] that is M0 3% · M1 6% · M2 8% · Final 13% (<a href="./project/milestones.html">milestones</a>; <a href="./assessment/rubrics.html#team-project-milestones">rubrics</a>)</td></tr><tr><td>Oral exams (weeks 8 and 14)</td><td>15%</td><td>15%</td><td>Two 15-minute exams, 🔴 AI off, 7.5% each (<a href="./assessment/oral-exams.html">oral exams</a>)</td></tr><tr><td>Reading responses and Seminar participation</td><td>10%</td><td>5%</td><td>150–250-word responses on Canvas, plus taking part in the Seminar (<a href="./assessment/rubrics.html#reading-responses-and-seminar-participation">rubric</a>)</td></tr><tr><td>Graduate work</td><td>—</td><td>20%</td><td>Presentation and discussant 6 · critique 3 · empirical study 11 (<a href="./graduate/">graduate/</a>)</td></tr></tbody></table><p><strong>The <a href="./assessment/">assessment guide</a> is part of this syllabus.</strong> It explains how points become your grade, drops, grace tokens, late work, make-ups, team grade adjustments, regrades, pass/fail and incompletes. I go through it in the first Seminar.</p><p><strong>Graded on evidence.</strong> Your grade rests on your commit history, your <code>AI_LOG.md</code>, your tests, checks anyone can reproduce, and an honest account of what doesn&#39;t work. UT Austin&#39;s CS 378 puts it this way, and so does this course: &quot;Feature count, repository size, token spend, prompt volume, and visual polish do not substitute for demonstrated behavior, reproducible checks, controlled engineering decisions, or honest limitations&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>). Naming a real limitation never costs points.</p><p><strong>Why nothing exam-like happens in week 15:</strong> Regulation H-1-a allows no quizzes or exams in lecture-recitation periods in the week before finals week. So the last quiz and oral exam 2 are in week 14, and the final defense uses the final exam slot in week 16.</p><h3 id="letter-grades" tabindex="-1">Letter grades <a class="header-anchor" href="#letter-grades" aria-label="Permalink to &quot;Letter grades&quot;">​</a></h3><p>The University of Idaho uses letter grades without plus or minus (Regulation E).</p><table tabindex="0"><thead><tr><th>Grade</th><th>Course percentage</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>90–100</td></tr><tr><td><strong>B</strong></td><td>80–89</td></tr><tr><td><strong>C</strong></td><td>70–79</td></tr><tr><td><strong>D</strong></td><td>60–69</td></tr><tr><td><strong>F</strong></td><td>below 60</td></tr></tbody></table><p>To earn a C or higher you must also have <strong>taken both oral exams and the final defense</strong> (<a href="./assessment/#letter-grades">details</a>).</p><p><strong>CS [5xxx]:</strong> a course with a D or F can&#39;t count toward graduate degree requirements (though it counts in your GPA), and you need a 3.00 GPA to stay in good standing and to graduate (College of Graduate Studies).</p><h3 id="late-work" tabindex="-1">Late work <a class="header-anchor" href="#late-work" aria-label="Permalink to &quot;Late work&quot;">​</a></h3><p>You have <strong>two grace tokens</strong>, each extending one individual deadline by 48 hours with no reason needed; each team also has one team token for M0, M1 or M2. After that, late work loses 10% of its points per day for up to three days. Tokens can&#39;t be used for quizzes, oral exams, the PR round, the final defense or other live events, which have make-up rules instead (<a href="#missed-meetings-and-make-up-work">section 12</a>), and no token can move work past the University&#39;s grade deadline. <strong>Running out of free credits is not a reason to be late</strong>, as UT Austin&#39;s course also says: switching to a fallback is part of the course. Full rules: <a href="./assessment/#late-work-and-grace-tokens">Late work and grace tokens</a>.</p><h3 id="passfail" tabindex="-1">Pass/fail <a class="header-anchor" href="#passfail" aria-label="Permalink to &quot;Pass/fail&quot;">​</a></h3><p>This course is letter-graded. <strong>CS [4xxx]:</strong> undergraduates may use the pass/fail option only for courses outside their major (B-10-a), so CS majors can&#39;t take this course pass/fail; others need a 2.00 GPA and their advisor&#39;s approval, and may take one such course a semester. <strong>CS [5xxx]:</strong> graduate students may take it pass/fail only if it is outside their designated major (or is a background or deficiency course), with the approval of their major professor and the dean of the College of Graduate Studies, and no more than 3 credits of a master&#39;s (9 of a doctorate) may be pass/fail (B-10-b). The deadline to switch is early in the term (the Registrar&#39;s <a href="https://www.uidaho.edu/registrar/dates-deadlines" target="_blank" rel="noreferrer">dates and deadlines</a>). I&#39;m not told who chose it: I report a letter grade, and the Registrar records a C or higher as P. For undergraduates a D stays a D; for graduate students a D is recorded as an F (B-10-d).</p><h3 id="incompletes" tabindex="-1">Incompletes <a class="header-anchor" href="#incompletes" aria-label="Permalink to &quot;Incompletes&quot;">​</a></h3><p>Apart from the academic-integrity case in <a href="#academic-integrity">section 12</a> (FSH 2300 F-9), an Incomplete (I) is possible only under catalog Regulation F: you have been attending and doing passing work until near the end (the regulation&#39;s cutoff is three weeks before the close of the semester), and an extenuating circumstance, such as serious illness or a death in the family, makes it impossible to finish on time. We agree it together, I set out in writing what&#39;s left to do and by when, and I record a grade that applies if the work isn&#39;t completed. Running out of time because of procrastination doesn&#39;t qualify. You must finish by the Regulation F-2 deadline (the last day of the following summer for a fall Incomplete, the last day of the following fall semester for a spring or summer one); otherwise the I changes automatically to the grade I recorded. You can&#39;t graduate with an I on your record (F-3), and graduate students on provisional admission can&#39;t move to regular status with an I on their record (College of Graduate Studies). If something serious happens, talk to me as early as you can.</p><h2 id="9-ai-use-policy" tabindex="-1">9. AI use policy <a class="header-anchor" href="#9-ai-use-policy" aria-label="Permalink to &quot;9. AI use policy&quot;">​</a></h2><p>This course <strong>requires</strong> AI for code. The question is never &quot;how much AI did you use&quot; but &quot;can you explain, verify and take responsibility for what you shipped&quot;. The rule is the one Michigan&#39;s EECS 498 uses: <strong>if you can&#39;t explain it, you didn&#39;t build it</strong> (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">EECS 498</a>). Every task is labeled with one of three levels, always in words as well as color.</p><table tabindex="0"><thead><tr><th>Level</th><th>When</th><th>The complete list</th></tr></thead><tbody><tr><td>🟢 <strong>AI on</strong></td><td>Building, exploring, testing, reviewing your own work</td><td>Writing and refactoring code; writing tests; exploring a codebase; configuring CI; running AI reviewers and analyzers; preparing slides and figures for a graduate presentation (disclosed on the last slide); analysis code for the graduate study (disclosed). Everything not listed below is 🟢 AI on</td></tr><tr><td>🟡 <strong>AI limited</strong></td><td>Documents where the decisions are yours</td><td><strong><code>SPEC.md</code>:</strong> you write the problem, the criteria and the out-of-scope list; an AI may critique it. <strong><code>DESIGN.md</code>:</strong> an agent may explore the codebase and propose options; the decisions and their reasons are yours. <strong><code>TASKS.md</code>:</strong> you split the design into tasks; an AI may critique the split. <strong><code>AGENTS.md</code>:</strong> you write it; an AI may critique it. <strong><code>THREAT_MODEL.md</code>:</strong> an AI may help brainstorm attacks; the analysis and decisions are yours. <strong>The team&#39;s final report:</strong> the AI may help with tables, figures and checking claims against the repository, but the limitations, reflection and contribution sections are written by the team (🔴). <strong>The graduate study</strong> (protocol, interim report and paper): analysis code may be AI-assisted and is disclosed; the research question, the design and the prose are yours (🔴). <strong>Any other document a brief marks 🟡 AI limited</strong> follows that brief. Log the help you used in <code>AI_LOG.md</code></td></tr><tr><td>🔴 <strong>AI off</strong></td><td>Checks of your understanding, and writing you sign</td><td>Due-date quizzes · oral exams and their retake · the final defense&#39;s individual questions · reading responses · reflections, including the reflection parts of the final report · peer evaluations · PR descriptions and review comments you sign (in the team fork, the PR round and upstream; an AI reviewer may run alongside you, and you may compare after writing your own) · your Seminar question for a graduate presentation · graduate critiques and discussant questions · the graduate study&#39;s prose · any other task a brief marks 🔴 AI off</td></tr></tbody></table><p><strong>If two labels ever seem to disagree,</strong> follow the stricter one and ask. Using AI on 🔴 AI-off work, or beyond what a 🟡 AI-limited label allows, is academic dishonesty under the University&#39;s Student Code of Conduct (<a href="#academic-integrity">section 12</a>).</p><ul><li><strong>Disclose.</strong> Every repository has an <code>AI_LOG.md</code> (<a href="./templates/AI_LOG.html">template</a>): the sessions, tools and models, what was delegated, and what was verified and how. Commits made with AI help end with <code>Assisted-by: [tool and model]</code>. Every PR&#39;s description has an AI disclosure section.</li><li><strong>Stricter policies win.</strong> When you contribute to someone else&#39;s project, including the parent of the class codebase, its AI policy overrides the course&#39;s whenever it is stricter (<a href="./project/contribution-rules.html">contribution rules</a>).</li><li><strong>Credit others.</strong> Code, text or data from a person, a paper or a website is credited where you use it, with its license.</li></ul><h2 id="10-agent-safety-and-data" tabindex="-1">10. Agent safety and data <a class="header-anchor" href="#10-agent-safety-and-data" aria-label="Permalink to &quot;10. Agent safety and data&quot;">​</a></h2><h3 id="the-agent-safety-contract" tabindex="-1">The agent safety contract <a class="header-anchor" href="#the-agent-safety-contract" aria-label="Permalink to &quot;The agent safety contract&quot;">​</a></h3><p>You read the <a href="./setup/safety-contract.html">agent safety contract</a> in week 0 and sign it on Canvas in week 1. Each rule starts the week it is taught, and the course builds protections around you: Codespaces, kits with an approval gate and a workspace guard, a worthless canary instead of a real key in the injection lab, and graded work in a class fork rather than maintainers&#39; repositories. In short:</p><table tabindex="0"><thead><tr><th>Rule</th><th>In practice</th><th>Taught in</th></tr></thead><tbody><tr><td>1. <strong>The data rule</strong></td><td>Free tiers see only public open-source code and the course kits (<a href="#the-data-rule">below</a>)</td><td>Weeks 0–1</td></tr><tr><td>2. <strong>Approvals stay on</strong></td><td>Every command and every write needs your approval unless you allowlisted that exact, read-only command. No auto-approve, &quot;yolo&quot; or skip-permissions modes; an agent never edits its own permissions</td><td>Week 1</td></tr><tr><td>3. <strong>Untrusted code runs in a sandbox</strong></td><td>Repositories you didn&#39;t write are opened only in a Codespace or a dev container, cloned from their URL</td><td>Weeks 2 and 4</td></tr><tr><td>4. <strong>No real secrets near an agent</strong></td><td>An agent session that reads untrusted text has nothing worth stealing in reach</td><td>Weeks 1 and 4</td></tr><tr><td>5. <strong>Scoped tokens only</strong></td><td>Fine-grained, one repository, fewest permissions, an expiry date</td><td>Weeks 4 and 13</td></tr><tr><td>6. <strong>Spending caps at zero</strong></td><td>No payment method on course accounts; nothing metered with a cap above zero or the lowest value allowed; never an agentic workflow whose per-run cap could exceed a free allowance</td><td>Weeks 0, 9 and 13</td></tr><tr><td>7. <strong>Save points before and after</strong></td><td>Commit before and after every agent task, on a branch or worktree; <code>main</code> protected</td><td>Weeks 1 and 13</td></tr><tr><td>8. <strong>Read before you adopt</strong></td><td>An MCP server, skill, rules file, Action or package is someone else&#39;s code until you&#39;ve read it; check and pin packages</td><td>Weeks 3 and 10</td></tr><tr><td>9. <strong>Verify, and say how</strong></td><td>Claims tagged observed or inferred; only observed ones count as verified</td><td>Weeks 1 and 6–7</td></tr><tr><td>10. <strong>No unattended agents in other people&#39;s spaces</strong></td><td>No agent posts, comments or opens anything in a repository you don&#39;t own without you reading it first</td><td>Weeks 9 and 12–15</td></tr><tr><td>11. <strong>Disclose AI help</strong></td><td><code>AI_LOG.md</code>, <code>Assisted-by:</code> trailers and the PR template&#39;s AI section</td><td>Week 1</td></tr></tbody></table><p>The contract adds three project rules: no real personal data, no human-subjects research without IRB approval, and nothing you&#39;d miss if an agent deleted it.</p><h3 id="the-data-rule" tabindex="-1">The data rule <a class="header-anchor" href="#the-data-rule" aria-label="Permalink to &quot;The data rule&quot;">​</a></h3><p>Free tiers may use your prompts to train their models. <strong>Use them only on public open-source code and the course kits; never on personal data, secrets, or code you may not share.</strong> That includes your own grades and feedback, classmates&#39; writing, unpublished research code, and anything an employer owns.</p><h3 id="privacy-of-your-work" tabindex="-1">Privacy of your work <a class="header-anchor" href="#privacy-of-your-work" aria-label="Permalink to &quot;Privacy of your work&quot;">​</a></h3><p>Your code is public on purpose: the team forks and the PR round only work in the open. Your grades and personal writing are not. University policy treats grades and graded work as private (FSH 4700 F-6, and FSH 2600, which applies FERPA, the US federal student-records law), so:</p><ul><li><strong>In public repositories,</strong> under your GitHub username: code, tests, CI, <code>SPEC.md</code>, <code>DESIGN.md</code>, <code>TASKS.md</code>, <code>AGENTS.md</code>, <code>THREAT_MODEL.md</code>, <code>EVAL_PLAN.md</code>, <code>AI_LOG.md</code>, PR descriptions and code review comments.</li><li><strong>On Canvas only:</strong> reading responses, reflections, peer evaluations, the final report, graduate critiques, discussant notes and study papers, quiz and oral-exam results, the signed safety contract, and all grades and feedback.</li><li><strong>Never commit</strong> grades, feedback, reflections, peer evaluations, classmates&#39; real names (use GitHub usernames), your student ID, or real personal data about anyone.</li></ul><p>Details: <a href="./assessment/#privacy-of-your-work">Privacy of your work</a>.</p><h2 id="11-tools-and-cost" tabindex="-1">11. Tools and cost <a class="header-anchor" href="#11-tools-and-cost" aria-label="Permalink to &quot;11. Tools and cost&quot;">​</a></h2><p>Required cost: <strong>$0</strong>, from free tiers, the GitHub Student Developer Pack, open-source tools and a department lab machine that serves open-weight models through Ollama to the class (one shared queue). Every layer (chat, IDE agent, CLI agent, background agents, AI review, an LLM API for the kits, local models, CI, static analysis, secret scanning, testing, evals, sandboxes) has a primary free tool and two fallbacks, listed with their current limits in <a href="./TOOLS.html">Tool Handout</a>. Department-funded API credits are an optional upgrade, never assumed. Paying for a tool is never needed for full marks.</p><p>Two facts shape the design. Copilot&#39;s student offer has a small model allowance, so use it lightly (completions, light chat), never as your main agent. Heavy agent work is spread across several separate free allowances and the lab machine. The kits read three environment variables, <code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code> and <code>LLM_MODEL</code>, for any OpenAI-compatible API, so switching provider (or moving to the lab machine) is a configuration change, not a code change.</p><p>Free tiers change without notice. When a tool stops working for you, switching to the fallback is part of the course: see <a href="./resources/troubleshooting.html">Troubleshooting</a>.</p><h2 id="12-course-policies" tabindex="-1">12. Course policies <a class="header-anchor" href="#12-course-policies" aria-label="Permalink to &quot;12. Course policies&quot;">​</a></h2><h3 id="attendance-and-participation" tabindex="-1">Attendance and participation <a class="header-anchor" href="#attendance-and-participation" aria-label="Permalink to &quot;Attendance and participation&quot;">​</a></h3><p>The Seminar and the Lab are where most of the learning happens. Attendance isn&#39;t scored on its own; it counts through <strong>Seminar participation</strong> (part of the reading-responses component) and the <strong>Lab checkoff</strong> (part of Labs and assignments). Your lowest three Seminar scores and your lowest lab week are dropped, which covers a few ordinary missed days. You&#39;re responsible for catching up on what you missed: every lab is written step by step, and office hours are there for catch-up help.</p><h3 id="missed-meetings-and-make-up-work" tabindex="-1">Missed meetings and make-up work <a class="header-anchor" href="#missed-meetings-and-make-up-work" aria-label="Permalink to &quot;Missed meetings and make-up work&quot;">​</a></h3><ul><li><strong>Absences the University recognizes</strong> (catalog Regulation M-1): official university activities, your own illness, family illness or care, or other compelling circumstances. Tell me as soon as you can (before the absence, for official activities). You can make up a Lab checkoff for <strong>full credit within one week</strong> in office hours; a missed quiz is excused or made up within a week; a missed oral exam is rescheduled without penalty; deadlines move without using a token.</li><li><strong>Religious observance</strong> (Regulation M-3): quizzes, oral exams, presentations and the final defense are rescheduled. Tell me as early as you can.</li><li><strong>Other absences:</strong> a Lab checkoff shown in office hours within 48 hours earns up to 3 of its 5 points. A missed quiz scores zero, which the two quiz drops are there to absorb.</li></ul><p>Full rules: <a href="./assessment/#absences-and-make-up-work">Absences and make-up work</a>. Both oral-exam windows and the final exam slot are posted on Canvas in week 1.</p><h3 id="recording-of-class-sessions" tabindex="-1">Recording of class sessions <a class="header-anchor" href="#recording-of-class-sessions" aria-label="Permalink to &quot;Recording of class sessions&quot;">​</a></h3><p>Students may record Seminars and Labs only with my consent or as an approved CDAR accommodation, and in either case must tell me first (FSH 4700 F-8). Concept talks I record are posted only on Canvas. Oral exams and final-defense questions are recorded only with your consent, kept where only staff can see them, and deleted once grades are final.</p><h3 id="academic-integrity" tabindex="-1">Academic integrity <a class="header-anchor" href="#academic-integrity" aria-label="Permalink to &quot;Academic integrity&quot;">​</a></h3><p><strong>Disclosure is the rule.</strong> Honest disclosure of AI use in <code>AI_LOG.md</code>, <code>Assisted-by:</code> trailers and PR descriptions is never penalized, even when an agent did most of the typing.</p><p>The University of Idaho Student Code of Conduct and Resolution Process (FSH 2300) applies. In this course, academic dishonesty includes: using AI on 🔴 AI-off work or beyond a 🟡 AI-limited label (the Code names &quot;reliance on prohibited technological assistance/artificial intelligence tools&quot;, FSH 2300 E-1.c); <strong>fabricating evidence</strong> such as test results, mutation scores, eval numbers, CI runs, security findings, <code>AI_LOG.md</code> entries or study data; submitting someone else&#39;s code or writing as your own, including a generated PR description or review comment presented as yours; misrepresenting your contribution to a team; reusing work from another course without both instructors&#39; approval; and having someone else take your quiz, oral exam or defense questions.</p><p>There are two separate processes, and they never mix:</p><ol><li><strong>&quot;Explain it or redo it&quot; is a learning conversation, not a sanction.</strong> If you can&#39;t yet explain part of your own work, or your <code>AI_LOG.md</code> doesn&#39;t seem to match the repository, we talk for about 10 minutes. If you still can&#39;t explain it, you redo that part within 7 days and it is graded on the normal rubric, with no penalty.</li><li><strong>Suspected academic dishonesty goes through the University&#39;s process.</strong> If I suspect it, I will tell you and report it to the Dean of Students, as FSH 2300 requires. <strong>No grade consequence is applied until that process has concluded</strong> and its decision has been communicated to you; if grades are due before then, an Incomplete is entered until it is resolved (FSH 2300 F-9). If the University&#39;s process finds you responsible, the most I can apply as an academic consequence is an F in the course (catalog Regulation O-2). The Dean of Students explains your options and rights.</li></ol><p>The course doesn&#39;t use AI detectors. Even on commits, detectors that look for agent-written code reach only about one-third precision at realistic rates (<a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">Horikawa et al.</a>); recorded attribution is the only reliable record. Full details: <a href="./assessment/#academic-integrity">Academic integrity</a>.</p><h3 id="learning-civility" tabindex="-1">Learning civility <a class="header-anchor" href="#learning-civility" aria-label="Permalink to &quot;Learning civility&quot;">​</a></h3><p>In any environment in which people gather to learn, it is essential that all members feel as free and safe as possible in their participation. Everyone in this course is expected to be respectful and civil to one another in discussion, in action, in teaching and in learning, and that includes code review: review the code, never the person. If our class interactions fall short of that, please talk with me; you can also contact the <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">Dean of Students</a> (208-885-6757), the <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">Counseling and Mental Health Center</a>&#39;s confidential services (208-885-6716), or the <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">Office of Civil Rights and Investigations</a> (208-885-4285). See also FSH 4170 (Maintaining Instructional Order).</p><h3 id="firearms" tabindex="-1">Firearms <a class="header-anchor" href="#firearms" aria-label="Permalink to &quot;Firearms&quot;">​</a></h3><p>The University of Idaho bans firearms from its property, with only limited exceptions (<a href="https://www.uidaho.edu/policies/apm/95/12" target="_blank" rel="noreferrer">University policy APM 95.12</a>). One exception lets holders of the licenses described in Idaho Code 18-3309(2), such as an Idaho enhanced concealed carry license, carry a firearm that stays concealed at all times; it doesn&#39;t apply in residence halls and some large venues. If you see a firearm on University property, or anyone who appears to be a danger, call 911.</p><h2 id="13-accessibility-and-support" tabindex="-1">13. Accessibility and support <a class="header-anchor" href="#13-accessibility-and-support" aria-label="Permalink to &quot;13. Accessibility and support&quot;">​</a></h2><h3 id="accessibility-and-accommodations" tabindex="-1">Accessibility and accommodations <a class="header-anchor" href="#accessibility-and-accommodations" aria-label="Permalink to &quot;Accessibility and accommodations&quot;">​</a></h3><p>The University of Idaho is committed to ensuring an accessible learning environment where course or instructional content are usable by all students and faculty. If you believe you require disability-related academic adjustments for this class (including pregnancy-related disabilities), please contact the <a href="https://www.uidaho.edu/student-resources/disability-accessibility-resources" target="_blank" rel="noreferrer">Center for Disability Access and Resources (CDAR)</a> to discuss eligibility. A current accommodation letter from CDAR is required before any modifications, above and beyond what is otherwise available for all other students in this class, will be provided. Disability-related academic adjustments are not retroactive. CDAR: Bruce M. Pitman Center, Suite 127; 208-885-6307; <a href="mailto:cdar@uidaho.edu" target="_blank" rel="noreferrer">cdar@uidaho.edu</a>; <a href="https://www.uidaho.edu/cdar" target="_blank" rel="noreferrer">services and hours</a>. CDAR also arranges adjustments for <a href="https://www.uidaho.edu/student-resources/disability-accessibility-resources/pregnancy-accommodations" target="_blank" rel="noreferrer">pregnancy and related conditions</a>.</p><p>Several adjustments are open to <strong>everyone</strong>, with or without a letter: typed answers and a written-first version for oral exams; a private slot for your final-defense questions; screen-reader-friendly quizzes (<a href="./assessment/#accommodations">full list</a>). Slides are plain text, every lab is written step by step, and Codespaces runs in a browser on modest laptops. If a health condition, time zone, device or connectivity issue affects your work, tell me in week 1 so we can plan together.</p><h3 id="discrimination-harassment-and-sexual-misconduct" tabindex="-1">Discrimination, harassment and sexual misconduct <a class="header-anchor" href="#discrimination-harassment-and-sexual-misconduct" aria-label="Permalink to &quot;Discrimination, harassment and sexual misconduct&quot;">​</a></h3><p>As a U of I employee, I must report to the Office of Civil Rights and Investigations any information I receive about possible sex-based misconduct in a university program, so I can&#39;t keep it confidential (FSH 6100). For confidential support, contact the Counseling and Mental Health Center (208-885-6716). To report, or to learn your options, contact <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">OCRI</a>: <a href="mailto:ocri@uidaho.edu" target="_blank" rel="noreferrer">ocri@uidaho.edu</a>, 208-885-4285, 530 S Asbury St., Suite 5. In an emergency, call 911.</p><h3 id="your-well-being" tabindex="-1">Your well-being <a class="header-anchor" href="#your-well-being" aria-label="Permalink to &quot;Your well-being&quot;">​</a></h3><p>If stress, health, money, housing or anything else gets in the way, you don&#39;t have to handle it alone. The Counseling and Mental Health Center offers free counseling (208-885-6716; 24/7 crisis help: option 3). You can also ask the Dean of Students for support through <a href="https://www.uidaho.edu/student-resources/dean-of-students/vandalcare" target="_blank" rel="noreferrer">VandalCARE</a>, including a self-referral, or refer a classmate you&#39;re worried about. In an emergency, call 911.</p><h3 id="if-you-fall-behind" tabindex="-1">If you fall behind <a class="header-anchor" href="#if-you-fall-behind" aria-label="Permalink to &quot;If you fall behind&quot;">​</a></h3><p>Each week builds on the last, so act early. Do each lab&#39;s <strong>Minimum to keep up</strong> box first. Tell your team early if you&#39;re behind on team work: a short message now beats a bad peer evaluation later. Office hours exist for &quot;I don&#39;t understand what the agent did&quot;.</p><h3 id="student-resources" tabindex="-1">Student resources <a class="header-anchor" href="#student-resources" aria-label="Permalink to &quot;Student resources&quot;">​</a></h3><ul><li><strong>Technology help:</strong> the OIT <a href="https://www.uidaho.edu/student-resources/technical-support" target="_blank" rel="noreferrer">IT Service Desk</a> (TLC 128), 208-885-HELP (4357); requests at <a href="https://support.uidaho.edu/" target="_blank" rel="noreferrer">support.uidaho.edu</a>. For course tools, see <a href="./resources/troubleshooting.html">troubleshooting</a> first.</li><li><strong>Library:</strong> <a href="https://www.lib.uidaho.edu/" target="_blank" rel="noreferrer">lib.uidaho.edu</a>, including help finding and reading research papers.</li><li><strong>Tutoring and study help:</strong> <a href="https://www.uidaho.edu/student-resources/academic-support/tutoring" target="_blank" rel="noreferrer">Vandals Tutoring</a> (drop-in), <a href="https://www.uidaho.edu/student-resources/academic-support/peer-assisted-study-sessions" target="_blank" rel="noreferrer">SI-PASS</a> (peer-led study sessions), the <a href="https://www.uidaho.edu/student-resources/academic-support/writing-center" target="_blank" rel="noreferrer">Writing Center</a> (which also helps with graduate papers), Academic Coaching and the Computer Science Assistance Center (<a href="https://www.uidaho.edu/student-resources/academic-support" target="_blank" rel="noreferrer">all academic support</a>).</li><li><strong>Dean of Students:</strong> <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">support, advocacy and student conduct</a>, TLC 232, 208-885-6757</li><li><strong>Counseling and Mental Health Center:</strong> <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">free counseling</a> for any student enrolled for at least one credit; Mary Forney Hall, 3rd floor; 208-885-6716 (24/7 crisis help: option 3)</li><li><strong>Vandal Food Pantry:</strong> <a href="https://www.uidaho.edu/student-resources/dean-of-students/basic-needs-food-insecurity-resources" target="_blank" rel="noreferrer">free food for any student</a>, Shoup Hall 105; the Dean of Students also offers emergency meal swipes and basic-needs kits</li><li><strong>Green Dot:</strong> the University&#39;s <a href="https://www.uidaho.edu/student-resources/health-wellness/violence-prevention-center" target="_blank" rel="noreferrer">violence-prevention program</a></li><li><strong>Graduate students:</strong> the <a href="https://www.uidaho.edu/graduate-studies" target="_blank" rel="noreferrer">College of Graduate Studies</a> for questions about graduate credit and policies.</li></ul><h2 id="14-why-the-course-looks-like-this" tabindex="-1">14. Why the course looks like this <a class="header-anchor" href="#14-why-the-course-looks-like-this" aria-label="Permalink to &quot;14. Why the course looks like this&quot;">​</a></h2><p>The design comes from a review, in November 2026, of comparable upper-division and graduate courses, the research on AI in software engineering, and the $0 tool landscape. The short version is in <a href="./research/design-rationale.html">Why the Course Looks Like This</a> and the full one in <a href="./research/landscape-report-2026-11.html">Landscape Report: Teaching Agentic Software Engineering to Seniors and Graduate Students</a>; the notes behind them are in <code>research/notes/</code> (<a href="./research/notes/courses-upper-division.html">courses</a>, <a href="./research/notes/evidence-senior.html">evidence</a>, <a href="./research/notes/tools-senior.html">tools</a>).</p><p><strong>Courses this one learns from.</strong></p><ul><li><strong>UT Austin CS 378, Agentic Software Engineering</strong>, the closest course in level, gives this course its core triad (&quot;what you specify, what you delegate, and what you verify&quot;), the 7-minute AI-free quiz on each homework&#39;s due date, homeworks that arrive in &quot;beats&quot; where the spec changes mid-assignment, the peer PR round on a fixed one-week clock, and a final graded on &quot;demonstrated behavior, reproducible checks… or honest limitations&quot; rather than feature count. It also says plainly that running out of credits is no excuse for a missing homework (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>; <a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">schedule</a>).</li><li><strong>Michigan EECS 498 (AASE)</strong> replaced its own &quot;build the agent&quot; lab with work inside Aider&#39;s real codebase, &quot;About 20,000 lines of Python with 12,000 lines of tests&quot;, and requires &quot;Learn, then design, then build&quot;, because &quot;A one-shot prompt gives you the model&#39;s design, not yours&quot; (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03 slides</a>). It runs at $0 on small local models on purpose: &quot;A small model punishes sloppy engineering visibly; that is the point&quot; (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">syllabus</a>). So this course keeps its own agent to a one-week lab and then moves into a real codebase.</li><li><strong>CMU 17-313, Foundations of Software Engineering</strong>, builds on a class fork of opencode, grades &quot;a snapshot of your repository (including open branches and PRs)&quot;, and says &quot;The PR does not need to be merged yet&quot; (<a href="https://cmu-313.github.io/assignments/P2/2_firstsprint/" target="_blank" rel="noreferrer">P2B</a>). This course&#39;s Tier 1 is that model.</li><li><strong>Stanford CS146S</strong> puts students on unfamiliar open-source repositories early (an <code>AGENTS.md</code> for &quot;a repo you did not write&quot;, a three-repository readiness comparison) and insists on scoped claims (<a href="https://github.com/mihail911/modern-software-dev-assignments/blob/df18839a81/week5/assignment.md" target="_blank" rel="noreferrer">W5 spec</a>): the source of the observed/inferred habit.</li><li><strong>CU Boulder CSCI 7000-05</strong> supplies the presentation rubric and the &quot;tool experience report&quot; option (<a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperPresentation.html" target="_blank" rel="noreferrer">presentations</a>; <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperCritiques.html" target="_blank" rel="noreferrer">critiques</a>), and UIdaho&#39;s own joint-listed CS courses supply the graduate sentence (<a href="https://catalog.uidaho.edu/courses/cs/" target="_blank" rel="noreferrer">catalog</a>).</li></ul><p><strong>The evidence behind the main choices.</strong></p><table tabindex="0"><thead><tr><th>Choice</th><th>Evidence</th></tr></thead><tbody><tr><td>Verification is graded, not output</td><td>Maintainers of scikit-learn, Sphinx and pytest reviewed 296 test-passing agent PRs; their merge rate ran 24.2 points below the automated grader&#39;s (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR</a>). In a randomized trial, experienced open-source developers were 19% slower with early-2025 AI tools while believing they were faster (<a href="https://arxiv.org/abs/2507.09089" target="_blank" rel="noreferrer">Becker et al.</a>)</td></tr><tr><td>Quality gates in CI from week 9</td><td>After Cursor adoption in 807 repositories, lines added rose 281% in the first month and the gain faded within about two months, while static-analysis warnings (+29.7%) and complexity (+40.7%) stayed up (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">He et al.</a>)</td></tr><tr><td>Context engineering is measured (week 3)</td><td>In 441 repositories, agent-first repositories without a committed AI configuration file saw complexity rise 53%, against 27% with one; 73.8% of such files were never edited after the first commit (<a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">Denisov-Blanch et al.</a>). Performance fell with input length in all 18 models Chroma tested (<a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">context rot</a>)</td></tr><tr><td>Mutation score, not coverage (weeks 6–7)</td><td>On 3,909 real Python functions, LLM-written tests averaged 45.1% statement coverage and a 40.2% mutation score (<a href="https://arxiv.org/abs/2508.00408" target="_blank" rel="noreferrer">Huang et al.</a>); suites can reach 100% coverage with a 4% mutation score (<a href="https://arxiv.org/html/2506.02954v5" target="_blank" rel="noreferrer">MutGen</a>); LLM oracles capture actual rather than expected behavior (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou et al.</a>); and the ISSTA 2026 replication warns that both measures mislead when the code may already be buggy (<a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">Zhao et al.</a>)</td></tr><tr><td>Review measured against a defect key (week 9)</td><td>At Atlassian, 38.7% of AI review comments led to code changes, against 44.45% of human ones (<a href="https://arxiv.org/abs/2601.01129v2" target="_blank" rel="noreferrer">Tantithamthavorn et al.</a>); at Beko, average PR closure time rose from 5h52m to 8h20m (<a href="https://arxiv.org/abs/2412.18531" target="_blank" rel="noreferrer">Cihan et al.</a>); PRs reviewed only by review agents merged 45.2% of the time, against 68.4% for human-reviewed ones (<a href="https://arxiv.org/abs/2604.03196" target="_blank" rel="noreferrer">Chowdhury et al.</a>)</td></tr><tr><td>Security before broad agent access (week 4) and again for code (week 10)</td><td>Planted payloads made Cursor and Copilot run malicious commands up to 84% of the time (<a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">Liu et al.</a>); about half of functionally correct generated backends were exploitable (<a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">BaxBench</a>); injected text once made Copilot switch itself to auto-approve (<a href="https://cybersecuritynews.com/github-copilot-rce-vulnerability/" target="_blank" rel="noreferrer">CVE-2025-53773</a>)</td></tr><tr><td>Judges reported with κ (week 12)</td><td>High percent agreement hid large score gaps between LLM judges and humans (<a href="https://arxiv.org/abs/2406.12624" target="_blank" rel="noreferrer">Thakur et al.</a>); a judge that always says &quot;pass&quot; gets 95% agreement when 5% of outputs fail (<a href="https://hamel.dev/blog/posts/llm-judge/" target="_blank" rel="noreferrer">Husain</a>)</td></tr><tr><td>Oral exams and due-date quizzes</td><td>Students using a coding agent finished faster but understood less and extended their code worse without AI, and still preferred the agent (<a href="https://arxiv.org/abs/2607.26375" target="_blank" rel="noreferrer">Balepur et al.</a>)</td></tr><tr><td>Process graded, merges a bonus</td><td>In Michigan&#39;s EECS 481, 44% of student PRs to open-source projects were accepted, and the authors advise to &quot;avoid mandatory grading of whether pull requests are accepted&quot; (<a href="https://web.eecs.umich.edu/~weimerw/p/weimer-fse2023.pdf" target="_blank" rel="noreferrer">Fang et al.</a>). Of 118 contributor AI policies in 1,000 popular repositories, 78% allow AI-assisted contributions, 51% require disclosure and 74% require a human in the loop (<a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">Hora and Robbes</a>)</td></tr><tr><td>Disclosure rules instead of detection</td><td>Detectors of agent-written commits reach only 0.332 precision at realistic prevalence, so &quot;recorded attribution&quot; can&#39;t be replaced (<a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">Horikawa et al.</a>)</td></tr></tbody></table><p><strong>What the evidence doesn&#39;t settle.</strong> Better-designed studies find smaller and less certain speed effects than early claims: randomized Copilot rollouts at three companies found 26% more completed tasks, with juniors gaining most (<a href="https://pubsonline.informs.org/doi/fpi/10.1287/mnsc.2025.00535" target="_blank" rel="noreferrer">Cui et al.</a>), while a preregistered study found no difference for the developers who later maintained AI-assisted code (<a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">Borg et al.</a>). Nobody yet measures delivered value well. The week 14 debate is about exactly this, and the course asks you to hold your own claims to the same standard.</p>',148)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
